<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue'
import { onPullDownRefresh, onShow, onHide, onResize, onBackPress } from '@dcloudio/uni-app'
import AppIcon from '../../components/AppIcon.vue'
import DormPicker from '../../components/DormPicker.vue'
import AutoLoginSheet from '../../components/AutoLoginSheet.vue'
import ElectricityHistory from '../../components/ElectricityHistory.vue'
import NetworkDetails from '../../components/NetworkDetails.vue'
import CampusCardDetails from '../../components/CampusCardDetails.vue'
import InstallationSheet from '../../components/InstallationSheet.vue'
import {topInset} from '../../utils/layout'
import {isWeb,iosBrowser,standalone,webUpdateReady,reloadWebApp} from '../../utils/web-app'
import { useCampus } from '../../stores/campus'
import { services as serviceDefinitions, type ServiceId } from '../../data/services'
import { useDaylight, periods } from '../../composables/useDaylight'
import { CONTENT_VERSION } from '../../version'
import { checkForUpdate, updateStatus, pendingVersion } from '../../utils/updates'
import { scheduleBadge, badgeTone, kindLabels, type ScheduleItem } from '../../data/schedule'
const campus=useCampus(), time=useDaylight()
const services=computed(()=>serviceDefinitions.map(s=>{if(s.id==='network'){const n=campus.dashboard?.network||{},traffic=n.primary_metric==='traffic',value=traffic?n.remaining_gb:n.balance;return {...s,title:traffic?'校园网剩余流量':'校园网余额',value:value===null||value===undefined?'—':Number(value).toFixed(2),unit:traffic?'GB':'元',sub:n.plan_label||serviceStatus('network'),expiry:n.period?.end?String(n.period.end).slice(5).replace('-','月')+'日周期到期':n.period?.state==='not_started'?'尚未开启计费周期':'周期待同步'}}return {...s,value:({power:campus.dashboard?.electricity?.surplus,card:campus.dashboard?.card?.cardinfo?.cardbal,spend:campus.dashboard?.spending?.month_total} as Record<string,string|null>)[s.id]??'—',sub:serviceStatus(s.id),expiry:s.id==='power'&&campus.dashboard?.electricity?.cached&&campus.dashboard?.electricity?.observed_at?'上次采集 '+new Date(campus.dashboard.electricity.observed_at).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):''}}))
function powerStatus(){const p=campus.dashboard?.electricity;if(!campus.roomBinding)return '选择宿舍';if(p?.status==='connected')return p.supply_status||'已同步';if(p?.status==='authorization_required')return p.cached?'上次记录 · 待续登':'需要重新认证';if(p?.status==='unavailable')return p.cached?'上次记录 · 查询失败':'暂时无法查询';return campus.checking?'查询中':'尚未查询'}
function isServiceUnavailable(id:unknown){return (id==='card'||id==='spend')&&!campus.dashboard?.card?.enabled}
function serviceStatus(id:string){if((id==='card'||id==='spend')&&!isServiceUnavailable(id)){const c=campus.dashboard?.card;return !c?.bound?'恢复虚构校园卡数据':c.status==='stale'?'上次记录 · 待同步':c.syncing?'正在同步':id==='spend'&&!campus.dashboard?.spending?.complete?'消费明细待同步':'已同步'}return isServiceUnavailable(id)?'开发中，暂未开启':id==='power'?powerStatus():id==='library'?(campus.libraryNeedsLogin?'需续登':campus.scheduleError?'待同步':'已连接'):campus.dashboard?.network?.status==='connected'?'已同步':campus.dashboard?.network?.status==='stale'?'上次同步':'暂未同步'}
const tab=ref('home'), detail=ref<ServiceId|'connections'|'profile'|'about'|null>(null)
const showInstall=ref(false)
const showRoom=ref(false),showAutoLogin=ref(false),pageVisible=ref(true)
const showTime=ref(false), selectedDay=ref(new Date().getDate()), filter=ref('全部'), toastText=ref('')
const dayItems=ref<ScheduleItem[]|null>(null),agendaLoading=ref(false),agendaTop=ref(false),agendaBottom=ref(true),bindingBusy=ref(false)
const selectedDate=ref('')
const agendaError=ref('')
let agendaRequest=0
const agendaItems=computed<ScheduleItem[]>(()=>dayItems.value??campus.schedule)
const selectedHeading=computed(()=>{if(!selectedDate.value)return `${dateLabel.value}　星期${weekdays[time.now.value.getDay()]}`;const d=new Date(selectedDate.value+'T12:00:00');return `${d.getMonth()+1}月${d.getDate()}日　星期${weekdays[d.getDay()]}`})
async function selectAgendaDay(d:any){const request=++agendaRequest;selectedDay.value=d.day;selectedDate.value=d.date;campus.agendaDate=d.date;agendaLoading.value=true;agendaError.value='';dayItems.value=[];agendaTop.value=false;try{const result=await campus.fetchSchedule(d.date);if(request!==agendaRequest)return;campus.schedule=result.items;dayItems.value=null;campus.scheduleError=result.notice||'';agendaError.value=result.notice||'';agendaBottom.value=result.items.length>3}catch(e){if(request===agendaRequest)agendaError.value=(e as Error).message}finally{if(request===agendaRequest)agendaLoading.value=false}}
let agendaViewportHeight=uni.upx2px(285)
function measureAgenda(){uni.createSelectorQuery().select('.agenda-scroll').boundingClientRect((r:any)=>{if(r?.height)agendaViewportHeight=r.height}).exec()}
watch(()=>agendaItems.value.length,()=>nextTick(measureAgenda))
onResize(()=>nextTick(measureAgenda))
function onAgendaScroll(e:any){agendaTop.value=e.detail.scrollTop>3;agendaBottom.value=e.detail.scrollHeight-e.detail.scrollTop>agendaViewportHeight+4}
function openSchedule(){const date=selectedDate.value||week.value.find(d=>d.day===selectedDay.value)?.date||'';uni.navigateTo({url:`/pages/schedule/index?date=${encodeURIComponent(date)}`})}
const editName=ref(''),editRoom=ref(''), statusHeight=ref(24)
let toastTimer:ReturnType<typeof setTimeout>
const weekdays=['日','一','二','三','四','五','六']
const dateLabel=computed(()=>`${time.now.value.getMonth()+1}月${time.now.value.getDate()}日`)
watch(dateLabel,()=>{if(!selectedDate.value)selectedDay.value=time.now.value.getDate()})
const week=computed(()=>{const date=selectedDate.value?new Date(selectedDate.value+'T12:00:00'):new Date(time.now.value);const offset=(date.getDay()+6)%7;return Array.from({length:7},(_,i)=>{const day=new Date(date);day.setDate(date.getDate()-offset+i);return {day:day.getDate(),label:weekdays[day.getDay()],date:`${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`}})})
const activeService=computed(()=>services.value.find(s=>s.id===detail.value))
const detailTitle=computed(()=>activeService.value?.title||({library:'图书馆预约',connections:'服务连接',profile:'个人资料',about:'关于[应用名称]'} as Record<string,string>)[detail.value||'']||'')
const rootClass=computed(()=>[`period-${time.period.value.id}`,{'night':time.dark.value}])
function toast(text:string){toastText.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastText.value='',2500)}
function open(id:typeof detail.value){if(id==='library'){uni.navigateTo({url:'/pages/library/index'});return}if(isServiceUnavailable(id)){uni.showModal({title:'暂未开启',content:`${id==='card'?'校园卡余额':'本月支出'}功能开发中，暂未开启。`,showCancel:false,confirmText:'知道了'});return}detail.value=id;filter.value='全部';if(id==='profile'){editName.value=campus.nickname;editRoom.value=campus.room};uni.pageScrollTo({scrollTop:0,duration:0})}
function changeTab(id:string){detail.value=null;tab.value=id;uni.pageScrollTo({scrollTop:0,duration:0})}
function back(){detail.value=null}
function amount(value:string){return campus.masked?'••••':value}
async function saveProfile(){try{await campus.saveProfile(editName.value,editRoom.value);toast('资料已保存');back()}catch(e){toast((e as Error).message)}}
async function doLogin(){await campus.login();dayItems.value=null;changeTab('home')}
async function changeAgendaConsent(e:any){try{await campus.setAgendaEnabled(!!e.detail.value);dayItems.value=null;selectedDate.value='';selectedDay.value=time.now.value.getDate()}catch(error){toast((error as Error).message)}}
async function doLogout(){await campus.logout();dayItems.value=null;changeTab('home')}
function openService(){open('connections')}
function share(){toast('可分享本项目的开源源码')}
async function refresh(){await campus.checkServer();dayItems.value=null;agendaError.value=campus.scheduleError;uni.stopPullDownRefresh();toast(campus.server)}
function applyStatus(){
 // #ifdef H5
 const color=time.dark.value?'#121e34':'#eff7ff';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',color);document.documentElement.style.backgroundColor=color;document.body.style.backgroundColor=color
 // #endif
 // #ifdef APP-PLUS
 const p=(globalThis as any).plus;if(p?.navigator){p.navigator.setStatusBarStyle(time.dark.value?'light':'dark');p.navigator.setStatusBarBackground('transparent')}
 // #endif
}
onMounted(()=>{statusHeight.value=uni.getSystemInfoSync().statusBarHeight||0;campus.boot();applyStatus()})
onShow(()=>{void nextTick(measureAgenda);pageVisible.value=true;time.now.value=new Date();const changed=campus.agendaDate&&campus.agendaDate!==selectedDate.value;if(changed){selectedDate.value=campus.agendaDate;selectedDay.value=new Date(campus.agendaDate+'T12:00:00').getDate();dayItems.value=null;campus.schedule=[];agendaError.value=''}campus.agendaVisible=(!detail.value&&tab.value==='home')||detail.value==='library';if(changed){agendaLoading.value=true;void campus.checkServer().finally(()=>agendaLoading.value=false)}else campus.foreground();applyStatus();setTimeout(applyStatus,250)})
onHide(()=>{pageVisible.value=false;campus.agendaVisible=false})
onPullDownRefresh(refresh)
onBackPress(()=>{if(showInstall.value){showInstall.value=false;return true}if(showRoom.value){showRoom.value=false;return true}if(showAutoLogin.value){showAutoLogin.value=false;return true}if(showTime.value){showTime.value=false;return true}if(detail.value){back();return true}if(tab.value!=='home'){changeTab('home');return true}return false})
function selectTime(i:number|null){time.override.value=i;showTime.value=false;applyStatus();toast(i===null?'已恢复跟随手机时间':`正在预览${periods[i].label}壁纸`)}
function chooseRoom(){showRoom.value=true}
let homeTimer:ReturnType<typeof setInterval>|undefined
watch([tab,detail,pageVisible,()=>campus.authenticated,()=>campus.appActive],()=>{clearInterval(homeTimer);const active=pageVisible.value&&campus.appActive;campus.agendaVisible=active&&((tab.value==='home'&&!detail.value)||detail.value==='library');if(active&&tab.value==='home'&&!detail.value&&campus.authenticated)homeTimer=setInterval(()=>{if(!showRoom.value&&!showTime.value&&!showAutoLogin.value)void refresh()},10*60*1000)},{immediate:true})
watch(()=>time.dark.value,applyStatus)
onUnmounted(()=>clearInterval(homeTimer))
</script>

<template>
 <view v-if="campus.booting" class="boot-screen"><image src="/static/brand/icon-192.png"/><text>[应用名称]</text></view>
 <view v-else-if="!campus.authenticated" class="login-screen" :class="rootClass">
  <view class="login-wallpaper"><image src="/static/campus-times.png" :style="time.wallpaperStyle.value" mode="scaleToFill"/></view><view class="login-overlay"/>
  <view class="login-brand" :style="{paddingTop:topInset(40,statusHeight)}"><image src="/static/brand/icon-192.png"/><text class="login-brand-name">[应用名称]</text></view>
  <view class="login-card panel"><view class="login-card-heading"><text>前端离线演示</text></view><text class="login-caption">全部数据均为虚构，无需账号密码</text><button class="primary-btn login-button" @click="doLogin">进入演示</button></view>
 </view>
 <view v-else class="app" :class="rootClass">
  <view class="demo-notice">离线演示 · 全部数据均为虚构</view>
  <view v-if="!detail && tab==='home'" class="hero">
   <view class="wallpaper"><image class="wallpaper-sheet" src="/static/campus-times.png" :style="time.wallpaperStyle.value" mode="scaleToFill"/></view><view class="sky-glaze"/>
   <view v-if="time.dark.value" class="stars"><text v-for="n in 18" :key="n" :style="{left:((n*37)%97)+'%',top:((n*23)%70)+'%',animationDelay:n*.3+'s'}">✦</text></view>
   <view class="celestial" :class="time.dark.value?'moon':'sun'" :style="time.orb.value"><view v-if="time.dark.value" class="moon-crater"/></view><view class="hero-fade"/>
   <view class="hero-content" :style="{paddingTop:topInset(18,statusHeight)}"><view class="brand-row"><view class="brand"><view class="brand-dot"/>[应用名称]</view><view class="time-chip" @click="showTime=true"><AppIcon :name="time.dark.value?'moon':'sun'" :size="24"/><text>{{time.period.value.label}}</text><text class="mini-arrow">⌄</text></view></view><view class="hello-row"><view><text class="hello">{{time.period.value.title}}，{{campus.nickname}}</text><text class="greeting">{{time.hint.value}}</text></view></view></view>
  </view>
  <view v-if="detail" class="sub-header" :style="{paddingTop:topInset(16,statusHeight)}"><view class="back-btn" @click="back"><AppIcon name="back" :size="38"/></view><text>{{detailTitle}}</text><view style="width:60rpx"/></view>
  <view v-else-if="tab!=='home'" class="section-header" :style="{paddingTop:topInset(30,statusHeight)}"><text class="page-title">{{tab==='services'?'校园服务':'我的'}}</text></view>
  <view class="content" :class="{'home-content':!detail&&tab==='home'}"><view v-if="campus.showingCached" class="cache-strip panel" @click="refresh"><text>显示上次同步的数据</text><text>重新连接 ›</text></view><view v-if="webUpdateReady" class="web-update panel" @click="reloadWebApp"><text>有新版本可用</text><text>刷新更新 ›</text></view>
   <template v-if="!detail && tab==='home'">
    <view class="agenda-card panel"><view class="calendar"><view class="calendar-heading"><text>{{selectedHeading}}</text><view class="calendar-action" @click="openSchedule"><AppIcon name="calendar" :size="34"/></view></view><view class="week"><view v-for="d in week" :key="d.date" class="week-day" :class="{selected:d.day===selectedDay}" @click="selectAgendaDay(d)"><text>{{d.day}}</text><text class="week-letter">{{d.label}}</text><view v-if="d.day===time.now.value.getDate()" class="today-dot"/></view></view></view>
     <view class="agenda-divider"/><view v-if="agendaItems.length" class="agenda-window"><scroll-view class="agenda-scroll" scroll-y :show-scrollbar="false" @scroll="onAgendaScroll"><view class="timeline agenda-timeline"><view v-for="item in agendaItems" :key="item.id" class="timeline-row"><view class="time-track" :class="{active:!!item.library}"><view class="track-dot"/><text>{{item.time}}</text></view><view class="event-card agenda-event" @click="openSchedule"><view class="agenda-event-copy"><text class="event-name">{{item.title}}</text><text class="event-sub">{{item.subtitle}}</text></view><view v-if="item.library" class="agenda-state-stack"><text class="agenda-reservation">{{item.library.reservation_status_text}}</text><text class="agenda-state" :class="badgeTone(scheduleBadge(item))">{{scheduleBadge(item)}}</text></view><text v-else-if="item.kind" class="agenda-state" :class="{danger:item.kind==='exam'}">{{kindLabels[item.kind]}}</text></view></view></view></scroll-view><view v-if="agendaTop" class="agenda-fade agenda-fade-top"/><view v-if="agendaBottom&&agendaItems.length>3" class="agenda-fade agenda-fade-bottom"/></view>
     <view v-else class="empty-inline"><AppIcon name="calendar" :size="54"/><text>{{agendaLoading?'正在加载':(selectedDate?agendaError:campus.scheduleError)||'这一天暂无日程'}}</text></view>
    </view>
    <view v-if="selectedDate?agendaError:campus.scheduleError" class="agenda-alert"><text>{{selectedDate?agendaError:campus.scheduleError}}</text><text v-if="campus.libraryNeedsLogin" @click="showAutoLogin=true">{{campus.autoLoginEnabled?'查看演示说明':'查看演示说明'}} ›</text></view><view class="section-title"><text>校园账户</text><view @click="campus.masked=!campus.masked"><AppIcon :name="campus.masked?'eye-off':'eye'" :size="30"/><text>{{campus.lastChecked?'更新于 '+campus.lastChecked:'尚未同步'}}</text></view></view>
    <view class="account-grid"><view v-for="s in services" :key="s.id" class="account-card panel" :class="s.color" @click="open(s.id)"><view class="account-heading"><AppIcon :name="s.icon" :size="36"/><text>{{s.title}}</text></view><view v-if="isServiceUnavailable(s.id)" class="account-unavailable">开发中</view><view v-else class="account-value"><text v-if="s.unit==='元'" class="currency">¥</text><text>{{amount(s.value)}}</text><text v-if="s.unit==='度'||s.unit==='GB'" class="value-unit">{{s.unit}}</text></view><view class="account-foot">{{isServiceUnavailable(s.id)?'暂未开启':s.sub}}<text v-if="!isServiceUnavailable(s.id)"> ›</text></view><text v-if="s.expiry" class="network-expiry">{{s.expiry}}</text><view class="account-art"><AppIcon :name="s.icon" :size="72"/></view></view></view>
   </template>
   <template v-else-if="!detail && tab==='services'"><view class="service-grid"><view v-for="s in [...services,{id:'library',title:'图书馆预约',icon:'book',color:'purple',sub:'选座与预约记录'}]" :key="s.id" class="service-tile panel" @click="open(s.id as ServiceId)"><view class="service-icon" :class="s.color"><AppIcon :name="s.icon" :size="48"/></view><text class="tile-title">{{s.title}}</text><text class="tile-sub">{{s.sub}}</text></view></view></template>
   <template v-else-if="!detail && tab==='mine'">
    <view class="profile-card panel" @click="open('profile')"><view class="profile-avatar"><image src="/static/avatar.svg"/></view><view class="profile-info"><text>{{campus.nickname}}</text><text>{{campus.studentId}}</text></view><AppIcon name="chevron" :size="32"/></view>
    <view class="panel setting-list"><view class="setting" @click="open('connections')"><AppIcon name="link"/><text>服务状态</text><AppIcon name="chevron" :size="26"/></view><view class="setting" @click="open('profile')"><AppIcon name="home"/><text>个人资料与宿舍</text><text class="setting-value">{{campus.roomBinding?.room_name||'未绑定'}}</text><AppIcon name="chevron" :size="26"/></view><view class="setting" @click="showAutoLogin=true"><AppIcon name="lock"/><text>演示说明</text><text class="setting-value">{{campus.autoLoginEnabled?'已开启':'未开启'}}</text><AppIcon name="chevron" :size="26"/></view><view class="setting" @click="showTime=true"><AppIcon name="sun"/><text>时光与壁纸</text><text class="setting-value">{{time.override.value===null?'自动':time.period.value.label}}</text><AppIcon name="chevron" :size="26"/></view></view>
    <view class="panel setting-list"><view class="setting" @click="showInstall=true"><AppIcon name="home"/><text>安装与下载</text><AppIcon name="chevron" :size="26"/></view><view class="setting" @click="share"><AppIcon name="share"/><text>分享链接</text><AppIcon name="chevron" :size="26"/></view><view class="setting" @click="refresh"><AppIcon name="refresh"/><text>刷新数据</text><text class="setting-value">{{campus.checking?'刷新中':campus.lastChecked}}</text><AppIcon name="chevron" :size="26"/></view><view class="setting" @click="checkForUpdate(true)"><AppIcon name="refresh"/><text>检查更新</text><text class="setting-value">{{pendingVersion?'下次启动生效':CONTENT_VERSION}}</text><AppIcon name="chevron" :size="26"/></view><view class="setting" @click="open('about')"><AppIcon name="info"/><text>关于</text><AppIcon name="chevron" :size="26"/></view></view><button class="logout-btn" @click="doLogout">退出演示</button>
   </template>
   <template v-else-if="detail==='connections'"><view class="connection panel" v-for="s in [...services.filter(s=>s.id!=='spend'),{id:'library',title:'图书馆预约',icon:'book',color:'purple'}]" :key="s.id"><view class="service-icon" :class="s.color"><AppIcon :name="s.icon"/></view><view class="connection-info"><text>{{s.title}}</text><text v-if="s.id==='card'" @click="open('card')">{{campus.dashboard?.card?.bound?'虚构校园卡 · 查看详情 ›':'本地虚构校园卡 ›'}}</text><text v-else-if="s.id==='power'">{{campus.roomBinding?.room_name||'请选择并核对宿舍房间'}}</text></view><view class="status-pill">{{serviceStatus(s.id)}}</view></view><view class="connection panel"><view class="connection-info"><text>课表日程</text><text>显示本地虚构日程</text></view><switch :checked="campus.agendaEnabled" color="#287bf5" @change="changeAgendaConsent"/></view><view class="panel connection-note"><text>{{campus.server}}</text><view class="text-button" @click="refresh">刷新 ›</view></view></template>
   <template v-else-if="detail==='profile'"><view class="panel form"><text class="form-label">昵称</text><input v-model="editName" maxlength="12" placeholder="同学"/><text class="form-label">宿舍备注</text><input v-model="editRoom" maxlength="30" placeholder="可选"/><text class="form-hint">{{campus.roomBinding?.room_name||'电量查询尚未绑定房间'}}</text><view class="text-button" @click="chooseRoom">{{bindingBusy?'正在查询…':'选择查询房间 ›'}}</view></view><button class="primary-btn" @click="saveProfile">保存</button></template>
   <template v-else-if="detail==='about'"><view class="about panel"><image src="/static/brand/icon-192.png"/><text class="about-title">[应用名称]</text><text class="about-en">{{CONTENT_VERSION}}</text></view><view class="panel connection-note"><text>应用更新</text><text>{{updateStatus}}</text><view class="text-button" @click="checkForUpdate(true)">检查更新 ›</view></view></template>
   <template v-else-if="detail">
    <view v-if="detail!=='library'&&detail!=='network'&&detail!=='card'&&detail!=='spend'" class="detail-balance panel" :class="activeService?.color"><text class="balance-label">{{activeService?.title}}</text><view class="balance-number"><text v-if="detail!=='power'" class="balance-currency">¥</text>{{amount(activeService?.value||'—')}}<text v-if="detail==='power'" class="balance-unit">度</text></view><text class="detail-data-note">{{serviceStatus(detail)}}</text></view>
    <template v-if="detail==='card'||detail==='spend'"><CampusCardDetails :key="detail" :mode="detail" :dark="time.dark.value" :active="pageVisible&&campus.appActive"/></template>
    <template v-else-if="detail==='power'"><view class="panel detail-info"><view><text>房间</text><text>{{campus.roomBinding?.room_name||'未绑定'}}</text></view><view><text>供电状态</text><text>{{campus.dashboard?.electricity?.cached?'上次记录：':''}}{{campus.dashboard?.electricity?.supply_status||'尚未查询'}}</text></view><view class="power-actions"><text @click="chooseRoom">选择房间 ›</text><text @click="refresh">{{campus.checking?'正在刷新…':'刷新电量 ↻'}}</text></view></view><view v-if="campus.dashboard?.electricity?.status==='authorization_required'" class="power-auth-note panel"><text>{{campus.autoLoginEnabled?'自动续登暂未完成，可重试或更新演示设置。':'财务授权已过期，查看演示说明后可自动续登。'}}</text><view class="power-auth-actions"><text @click="refresh">重试查询</text><text @click="showAutoLogin=true">{{campus.autoLoginEnabled?'查看演示说明':'查看演示说明'}}</text></view></view><ElectricityHistory :dark="time.dark.value"/></template>
    <template v-else-if="detail==='network'"><NetworkDetails/></template>
   </template>
  </view>
